class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Matemáticas vs. Zombis',theme:ThemeData(brightness:Brightness.dark,colorSchemeSeed:const Color(0xffb8f34b),useMaterial3:true),home:const Game());}
class Q{final String topic,text,answer,hint;final List<String> options;const Q(this.topic,this.text,this.options,this.answer,this.hint);}
List<Q> buildBank(){
 final list=<Q>[];
 for(var i=1;i<=10;i++){final a=4+i*2,b=2+i,ans=a+b;list.add(Q('Enteros','Exploración '+i.toString()+': calcula '+a.toString()+' + '+b.toString()+'.',[ans.toString(),(ans+2).toString(),(ans-3).toString(),(a*b).toString()],ans.toString(),'Suma primero las unidades y luego las decenas.'));}
 for(var i=1;i<=5;i++){final d=5+i,a=1+i,b=2,ans=a+b;list.add(Q('Fracciones','Reto '+i.toString()+': calcula '+a.toString()+'/'+d.toString()+' + '+b.toString()+'/'+d.toString()+'.',[ans.toString()+'/'+d.toString(),(ans+1).toString()+'/'+d.toString(),ans.toString()+'/'+(d+1).toString(),(a*b).toString()+'/'+d.toString()],ans.toString()+'/'+d.toString(),'Los denominadores son iguales: suma solo los numeradores.'));}
 for(var i=1;i<=5;i++){final a=i+1,b=i/10,ans=a+b;final correct=ans.toStringAsFixed(1).replaceAll('.',',');list.add(Q('Decimales','Reto '+(i+5).toString()+': calcula '+a.toString()+' + '+b.toStringAsFixed(1).replaceAll('.',',')+'.',[correct,(ans+1).toStringAsFixed(1).replaceAll('.',','),(ans-.2).toStringAsFixed(1).replaceAll('.',','),(a*b).toStringAsFixed(1).replaceAll('.',',')],correct,'Alinea las comas decimales antes de sumar.'));}
 for(var i=1;i<=5;i++){final base=i+1,ans=base*base;list.add(Q('Potencias','Reto '+i.toString()+': ¿cuánto es '+base.toString()+'²?',[ans.toString(),(ans+base).toString(),(base*2).toString(),(ans-1).toString()],ans.toString(),'Elevar al cuadrado significa multiplicar el número por sí mismo.'));}
 for(var i=1;i<=5;i++){final root=i+5,sq=root*root;list.add(Q('Raíces','Reto '+(i+5).toString()+': ¿cuál es √'+sq.toString()+'?',[root.toString(),(root+1).toString(),(root-2).toString(),(sq~/2).toString()],root.toString(),'Busca el número que multiplicado por sí mismo produce el radicando.'));}
 for(var i=1;i<=5;i++){final x=i+2,c=i+3,result=2*x+c;list.add(Q('Ecuaciones','Reto '+i.toString()+': resuelve 2x + '+c.toString()+' = '+result.toString()+'.',['x = '+x.toString(),'x = '+(x+2).toString(),'x = '+(result-c).toString(),'x = '+(x-1).toString()],'x = '+x.toString(),'Resta '+c.toString()+' en ambos miembros y divide para 2.'));}
 for(var i=1;i<=5;i++){final a=i+2,b=i+1;list.add(Q('Álgebra','Reto '+(i+5).toString()+': reduce '+a.toString()+'x + '+b.toString()+'x + 4.',[''+(a+b).toString()+'x + 4',''+(a*b).toString()+'x + 4',''+(a+b+4).toString()+'x',''+(a-b).toString()+'x + 4'],(a+b).toString()+'x + 4','Suma los coeficientes de los términos que tienen x; conserva el término independiente.'));}
 for(var i=1;i<=5;i++){final unit=i+2,n=i+4,total=unit*n;list.add(Q('Proporcionalidad','Reto '+i.toString()+': cada paquete cuesta \$'+unit.toString()+'. ¿Cuánto cuestan '+n.toString()+'?',['\$'+total.toString(),'\$'+(total+unit).toString(),'\$'+(unit+n).toString(),'\$'+(total-unit).toString()],'\$'+total.toString(),'Multiplica el precio unitario por la cantidad de paquetes.'));}
 for(var i=1;i<=5;i++){final price=20+i*10,percent=10,discount=price~/10,finalPrice=price-discount;list.add(Q('Porcentajes','Reto '+(i+5).toString()+': un artículo de \$'+price.toString()+' tiene 10 % de descuento. Precio final:',['\$'+finalPrice.toString(),'\$'+discount.toString(),'\$'+(price+discount).toString(),'\$'+(finalPrice-5).toString()],'\$'+finalPrice.toString(),'El 10 % es la décima parte. Calcula el descuento y réstalo del precio.'));}
 for(var i=1;i<=4;i++){final base=4+i*2,height=3+i,area=base*height~/2;list.add(Q('Geometría','Reto '+i.toString()+': área de un triángulo de base '+base.toString()+' cm y altura '+height.toString()+' cm.',[''+area.toString()+' cm²',''+(base*height).toString()+' cm²',''+(base+height).toString()+' cm²',''+(area+2).toString()+' cm²'],area.toString()+' cm²','Multiplica base por altura y divide el resultado para 2.'));}
 for(var i=1;i<=3;i++){final a=4+i,b=2+i,c=2,volume=a*b*c;list.add(Q('Volumen','Reto '+(i+4).toString()+': volumen de un prisma '+a.toString()+' × '+b.toString()+' × 2 m.',[''+volume.toString()+' m³',''+(a*b).toString()+' m³',''+(a+b+c).toString()+' m³',''+(volume+4).toString()+' m³'],volume.toString()+' m³','Multiplica largo, ancho y altura.'));}
 for(var i=1;i<=3;i++){final center=4+i;list.add(Q(i<3?'Estadística':'Probabilidad',i<3?'Reto '+(i+7).toString()+': media de '+(center-2).toString()+', '+center.toString()+' y '+(center+2).toString()+'.':'Reto 10: hay 3 fichas verdes y 7 rojas. P(verde):',i<3?[center.toString(),(center+1).toString(),(center*3).toString(),(center-1).toString()]:['3/10','7/10','3/7','1/3'],i<3?center.toString():'3/10',i<3?'Suma los tres datos y divide para 3.':'Casos favorables sobre casos totales: 3 de 10.'));}
 return list;
}
final bank=buildBank();
class Defender{final int row,col;int hp=3;Defender(this.row,this.col);}
class Enemy{int row,hp=3;double col;Enemy(this.row,this.col);}
class Game extends StatefulWidget{const Game({super.key});@override State<Game> createState()=>_GameState();}
class _GameState extends State<Game>{
 final rnd=Random(),defs=<Defender>[],foes=<Enemy>[];int mission=0,wave=1,energy=100,score=0,lives=5,qi=0,shotRow=2,shotPulse=0;bool started=false,paused=false,won=false,alarmOn=false;String msg='',errorDetail='';
 static const missions=['Isla Verde','Desierto Racional','Volcán de Potencias','Glaciar Algebraico','Ciudad Proporcional','Fortaleza Matemática'];
 Q get q=>bank[qi%bank.length];
 String get objective=>['Resuelve 10 operaciones con enteros y gana confianza.','Supera 10 retos de fracciones y decimales.','Domina 10 potencias y raíces antes de llegar al cráter.','Resuelve 10 expresiones y ecuaciones para cruzar el glaciar.','Aplica proporcionalidad y porcentajes en 10 decisiones.','Integra geometría, volumen, estadística y probabilidad en 10 retos finales.'][min(mission,5)];
 bool get inDanger=>foes.any((e)=>e.col<1.6);
 void start()=>setState((){started=true;won=false;alarmOn=false;mission=0;wave=1;energy=100;score=0;lives=5;qi=0;shotPulse=0;msg='';errorDetail='';defs.clear();foes.clear();spawn(2);});
 void spawn(int n){for(var i=0;i<n;i++)foes.add(Enemy(rnd.nextInt(5),6+rnd.nextDouble()));}
 void place(int r,int c){if(paused||energy<50||c>4||defs.any((d)=>d.row==r&&d.col==c))return;setState((){energy-=50;defs.add(Defender(r,c));msg='Defensa lógica desplegada';});}
 double? valueOf(String s){final fraction=RegExp(r'(-?\d+)\s*/\s*(-?\d+)').firstMatch(s);if(fraction!=null){final b=double.parse(fraction.group(2)!);return b==0?null:double.parse(fraction.group(1)!)/b;}final m=RegExp(r'-?\d+(?:[\.,]\d+)?').firstMatch(s);return m==null?null:double.tryParse(m.group(0)!.replaceAll(',','.'));}
 int errorLevel(String chosen,String correct){final a=valueOf(chosen),b=valueOf(correct);if(a==null||b==null)return 2;final distance=(a-b).abs()/max(b.abs(),1);if(distance<=.25)return 1;if(distance<=1)return 2;return 3;}
 void answer(String v){if(paused)return;final current=q;setState((){final ok=v==current.answer,oldMission=mission;if(ok){energy=min(200,energy+35);score+=15;errorDetail='';if(foes.isNotEmpty){final closest=foes.reduce((a,b)=>a.col<b.col?a:b);shotRow=closest.row;shotPulse++;foes.remove(closest);msg='¡Impacto correcto! El proyectil eliminó al zombi objetivo.';}else{msg='¡Correcto! +35 de energía';}}else{final amount=errorLevel(v,current.answer);spawn(amount);msg=amount==1?'Error cercano: apareció 1 zombi.':amount==2?'Respuesta muy alejada: aparecieron 2 zombis.':'Respuesta sin relación: aparecieron 3 zombis.';errorDetail='Tu respuesta: '+v+'\nRespuesta correcta: '+current.answer+'\nConsecuencia: aparecieron '+amount.toString()+(amount==1?' zombi.':' zombis.')+'\nProcedimiento: '+current.hint;}for(final e in foes)e.col-=ok ? 0.18 : 0.65;for(final e in List<Enemy>.from(foes)){final hits=defs.where((d)=>d.row==e.row&&(d.col-e.col).abs()<.7).toList();if(hits.isNotEmpty){hits.first.hp--;e.hp--;if(hits.first.hp<=0)defs.remove(hits.first);}if(e.col<0){foes.remove(e);lives--;}}qi++;if(qi>=bank.length){won=true;return;}mission=qi~/10;wave=((qi%10)~/3)+1;if(mission!=oldMission){energy=min(200,energy+80);defs.clear();foes.clear();spawn(2+mission);msg='¡Isla liberada! Comienza '+missions[mission]+'.';}else if(foes.isEmpty){spawn(1+min(wave,3));}if(lives<=0){started=false;msg='La ciudad necesita otra estrategia';}if(inDanger&&!alarmOn){alarmOn=true;SystemSound.play(SystemSoundType.alert);HapticFeedback.heavyImpact();}else if(!inDanger){alarmOn=false;}});}
 @override Widget build(BuildContext c){if(!started)return Start(onStart:start,msg:msg);if(won)return Victory(score:score,onRestart:start);return Scaffold(backgroundColor:const Color(0xff07110c),body:SafeArea(child:LayoutBuilder(builder:(c,s){final wide=s.maxWidth>760;return Column(children:[Bar(mission:mission,wave:wave,exercise:(qi%10)+1,energy:energy,score:score,lives:lives,paused:paused,onPause:()=>setState(()=>paused=!paused)),MissionAlert(objective:objective,danger:inDanger),Expanded(child:wide?Row(children:[Expanded(child:Field(defs:defs,foes:foes,onCell:place,mission:mission,shotRow:shotRow,shotPulse:shotPulse)),SizedBox(width:390,child:Quiz(q:q,onAnswer:answer,msg:msg,errorDetail:errorDetail))]):Column(children:[Expanded(child:Field(defs:defs,foes:foes,onCell:place,mission:mission,shotRow:shotRow,shotPulse:shotPulse)),SizedBox(height:390,child:Quiz(q:q,onAnswer:answer,msg:msg,errorDetail:errorDetail))]))]);})));}
}
