  return Container(margin:const EdgeInsets.all(12),decoration:BoxDecoration(borderRadius:BorderRadius.circular(18),gradient:LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:colors[min(mission,5)]),border:Border.all(color:const Color(0xffd6f0bb),width:2)),clipBehavior:Clip.antiAlias,child:Stack(children:[Positioned(right:12,top:8,child:Text(scenery[min(mission,5)],style:const TextStyle(fontSize:28))),grid,...defenseViews,...enemyViews,hero,projectile]));
